 "lec-ii4": "<svg viewBox=\"0 0 320 140\" role=\"img\" aria-label=\"Dos barras: el banco HPL llega al cien por cien de la escala y el banco HPCG apenas al uno por ciento\">\n<text class=\"sv-t\" x=\"8\" y=\"30\">HPL · procesadores siempre ocupados</text>\n<rect class=\"sv-f\" x=\"8\" y=\"38\" width=\"304\" height=\"18\" rx=\"9\"/><rect class=\"sv-cmp\" x=\"8\" y=\"38\" width=\"304\" height=\"18\" rx=\"9\"/>\n<text class=\"sv-t\" x=\"8\" y=\"86\">HPCG · problema limitado por la memoria</text>\n<rect class=\"sv-f\" x=\"8\" y=\"94\" width=\"304\" height=\"18\" rx=\"9\"/><rect class=\"sv-cmp\" x=\"8\" y=\"94\" width=\"4\" height=\"18\" rx=\"2\"/>\n<text class=\"sv-tb\" x=\"20\" y=\"108\">≈ 1 %</text><text class=\"sv-ts\" x=\"312\" y=\"132\" text-anchor=\"end\">misma máquina, dos problemas distintos</text></svg>",
 "lec-ii5": "<svg viewBox=\"0 0 320 150\" role=\"img\" aria-label=\"Un rectángulo cuya altura es la potencia y su anchura el tiempo: su área es la energía\">\n<path class=\"sv-l\" d=\"M30 16v110h270\"/><text class=\"sv-ts\" x=\"26\" y=\"20\" text-anchor=\"end\">W</text><text class=\"sv-ts\" x=\"300\" y=\"142\" text-anchor=\"end\">horas</text>\n<rect x=\"30\" y=\"54\" width=\"220\" height=\"72\" style=\"fill:color-mix(in srgb,var(--nrg) 26%,transparent);stroke:var(--nrg);stroke-width:1.5\"/>\n<text class=\"sv-tb\" x=\"140\" y=\"96\" text-anchor=\"middle\">energía = potencia × tiempo</text>\n<path class=\"sv-l2\" d=\"M262 54v72\"/><text class=\"sv-ts\" x=\"266\" y=\"92\">altura:</text><text class=\"sv-ts\" x=\"266\" y=\"106\">potencia</text>\n<text class=\"sv-ts\" x=\"140\" y=\"44\" text-anchor=\"middle\">anchura: tiempo (8.760 h en un año)</text></svg>",
 "lec-ii6": "<svg viewBox=\"0 0 320 150\" role=\"img\" aria-label=\"Once barras, de hoy a dentro de diez años, cada una un 25 por ciento mayor que la anterior: la última es más de nueve veces la primera\">\n<path class=\"sv-l\" d=\"M20 128h290\"/><rect class=\"sv-cmp\" x=\"24.0\" y=\"117.4\" width=\"18\" height=\"10.6\" rx=\"2\" style=\"opacity:0.55\"/><rect class=\"sv-cmp\" x=\"50.5\" y=\"114.8\" width=\"18\" height=\"13.2\" rx=\"2\" style=\"opacity:0.59\"/><rect class=\"sv-cmp\" x=\"77.0\" y=\"111.4\" width=\"18\" height=\"16.6\" rx=\"2\" style=\"opacity:0.63\"/><rect class=\"sv-cmp\" x=\"103.5\" y=\"107.3\" width=\"18\" height=\"20.7\" rx=\"2\" style=\"opacity:0.67\"/><rect class=\"sv-cmp\" x=\"130.0\" y=\"102.1\" width=\"18\" height=\"25.9\" rx=\"2\" style=\"opacity:0.71\"/><rect class=\"sv-cmp\" x=\"156.5\" y=\"95.7\" width=\"18\" height=\"32.3\" rx=\"2\" style=\"opacity:0.75\"/><rect class=\"sv-cmp\" x=\"183.0\" y=\"87.6\" width=\"18\" height=\"40.4\" rx=\"2\" style=\"opacity:0.79\"/><rect class=\"sv-cmp\" x=\"209.5\" y=\"77.5\" width=\"18\" height=\"50.5\" rx=\"2\" style=\"opacity:0.83\"/><rect class=\"sv-cmp\" x=\"236.0\" y=\"64.8\" width=\"18\" height=\"63.2\" rx=\"2\" style=\"opacity:0.87\"/><rect class=\"sv-cmp\" x=\"262.5\" y=\"49.0\" width=\"18\" height=\"79.0\" rx=\"2\" style=\"opacity:0.91\"/><rect class=\"sv-cmp\" x=\"289.0\" y=\"29.3\" width=\"18\" height=\"98.7\" rx=\"2\" style=\"opacity:0.95\"/>\n<text class=\"sv-ts\" x=\"33\" y=\"142\" text-anchor=\"middle\">hoy</text><text class=\"sv-ts\" x=\"316\" y=\"142\" text-anchor=\"end\">+10 años</text>\n<text class=\"sv-tb\" x=\"24\" y=\"24\">cada barra = la anterior × 1,25</text><text class=\"sv-ts\" x=\"24\" y=\"40\">la última ≈ 9,3 veces la primera</text></svg>",
 "lec-ii7": "<svg viewBox=\"0 0 320 150\" role=\"img\" aria-label=\"Una balanza que compara solo una cosa, los vatios: a un lado un cerebro de 20 vatios, al otro un enchufe\">\n<path class=\"sv-l\" d=\"M160 30v86M70 46h180\"/><path class=\"sv-l\" d=\"M112 128h96\"/>\n<path class=\"sv-l\" d=\"M70 46l-26 40h52zM250 46l-26 40h52z\"/>\n<circle class=\"sv-cnt\" cx=\"70\" cy=\"80\" r=\"14\" style=\"opacity:.85\"/><text class=\"sv-ts\" x=\"70\" y=\"108\" text-anchor=\"middle\">un cerebro: 20 W</text>\n<rect class=\"sv-nrg\" x=\"236\" y=\"68\" width=\"28\" height=\"22\" rx=\"4\"/><path class=\"sv-l\" d=\"M244 68v-8M256 68v-8\"/><text class=\"sv-ts\" x=\"250\" y=\"108\" text-anchor=\"middle\">20 W de enchufe</text>\n<text class=\"sv-tb\" x=\"160\" y=\"20\" text-anchor=\"middle\">solo se pesan vatios</text><text class=\"sv-ts\" x=\"160\" y=\"146\" text-anchor=\"middle\">no se pesa ni el cálculo ni la inteligencia</text></svg>",
 "lec-iii1": "<svg viewBox=\"0 0 320 150\" role=\"img\" aria-label=\"Una bicicleta y un tren con su consumo; debajo, la pregunta de cuánta carga lleva cada uno\">\n<circle class=\"sv-l\" cx=\"40\" cy=\"78\" r=\"18\"/><circle class=\"sv-l\" cx=\"96\" cy=\"78\" r=\"18\"/><path class=\"sv-l\" d=\"M40 78l20-30h26l10 30M60 48l12 30h24M56 40h12\"/>\n<text class=\"sv-ts\" x=\"68\" y=\"112\" text-anchor=\"middle\">poco consumo</text>\n<rect class=\"sv-f\" x=\"150\" y=\"44\" width=\"150\" height=\"38\" rx=\"6\"/><rect class=\"sv-ink\" x=\"160\" y=\"52\" width=\"18\" height=\"12\" rx=\"2\" style=\"opacity:.55\"/><rect class=\"sv-ink\" x=\"188\" y=\"52\" width=\"18\" height=\"12\" rx=\"2\" style=\"opacity:.55\"/><rect class=\"sv-ink\" x=\"216\" y=\"52\" width=\"18\" height=\"12\" rx=\"2\" style=\"opacity:.55\"/><rect class=\"sv-ink\" x=\"244\" y=\"52\" width=\"18\" height=\"12\" rx=\"2\" style=\"opacity:.55\"/><rect class=\"sv-ink\" x=\"272\" y=\"52\" width=\"18\" height=\"12\" rx=\"2\" style=\"opacity:.55\"/>\n<circle class=\"sv-l\" cx=\"172\" cy=\"88\" r=\"6\"/><circle class=\"sv-l\" cx=\"278\" cy=\"88\" r=\"6\"/><path class=\"sv-l\" d=\"M140 96h170\"/>\n<text class=\"sv-ts\" x=\"225\" y=\"112\" text-anchor=\"middle\">mucho consumo</text>\n<text class=\"sv-tb\" x=\"160\" y=\"140\" text-anchor=\"middle\">¿cuánta carga lleva cada uno?</text></svg>",
 "lec-iii2": "<svg viewBox=\"0 0 320 150\" role=\"img\" aria-label=\"Cuatro esferas de reloj con unidades distintas: FLOP, vatios, julios y veces por año\">\n<circle class=\"sv-f\" cx=\"44\" cy=\"62\" r=\"30\"/><path class=\"sv-a svs-cmp\" d=\"M44 62l14 -20\"/><circle class=\"sv-cmp\" cx=\"44\" cy=\"62\" r=\"3\"/>\n<text class=\"sv-tb\" x=\"44\" y=\"112\" text-anchor=\"middle\">FLOP</text><text class=\"sv-ts\" x=\"44\" y=\"128\" text-anchor=\"middle\">cómputo total</text><circle class=\"sv-f\" cx=\"121\" cy=\"62\" r=\"30\"/><path class=\"sv-a svs-nrg\" d=\"M121 62l20 -10\"/><circle class=\"sv-nrg\" cx=\"121\" cy=\"62\" r=\"3\"/>\n<text class=\"sv-tb\" x=\"121\" y=\"112\" text-anchor=\"middle\">W</text><text class=\"sv-ts\" x=\"121\" y=\"128\" text-anchor=\"middle\">potencia</text><circle class=\"sv-f\" cx=\"198\" cy=\"62\" r=\"30\"/><path class=\"sv-a svs-nrg\" d=\"M198 62l-16 -18\"/><circle class=\"sv-nrg\" cx=\"198\" cy=\"62\" r=\"3\"/>\n<text class=\"sv-tb\" x=\"198\" y=\"112\" text-anchor=\"middle\">J</text><text class=\"sv-ts\" x=\"198\" y=\"128\" text-anchor=\"middle\">energía</text><circle class=\"sv-f\" cx=\"275\" cy=\"62\" r=\"30\"/><path class=\"sv-a svs-inf\" d=\"M275 62l22 4\"/><circle class=\"sv-inf\" cx=\"275\" cy=\"62\" r=\"3\"/>\n<text class=\"sv-tb\" x=\"275\" y=\"112\" text-anchor=\"middle\">×/año</text><text class=\"sv-ts\" x=\"275\" y=\"128\" text-anchor=\"middle\">eficiencia</text>\n<text class=\"sv-ts\" x=\"160\" y=\"146\" text-anchor=\"middle\">cuatro preguntas, cuatro unidades</text></svg>",
